const items = $input.all();

function extractString(text, key) {
  const regex = new RegExp(`"${key}"\\s*:\\s*"([^"]*)"`);
  const match = text.match(regex);
  return match ? match[1] : null;
}

function extractArray(text, key) {
  const marker = `"${key}"`;
  const keyPos = text.indexOf(marker);

  if (keyPos === -1) {
    return [];
  }

  const colonPos = text.indexOf(':', keyPos + marker.length);
  const start = text.indexOf('[', colonPos);

  if (start === -1) {
    throw new Error(`${key} array start not found`);
  }

  let depth = 0;
  let inString = false;
  let escaped = false;

  for (let i = start; i < text.length; i++) {
    const ch = text[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (ch === '\\') {
        escaped = true;
      } else if (ch === '"') {
        inString = false;
      }

      continue;
    }

    if (ch === '"') {
      inString = true;
      continue;
    }

    if (ch === '[') {
      depth++;
    } else if (ch === ']') {
      depth--;

      if (depth === 0) {
        const arrayText = text.substring(start, i + 1);
        return JSON.parse(arrayText);
      }
    }
  }

  throw new Error(`${key} array is incomplete`);
}

return items.map((item, index) => {
  try {
    let output = String(item.json.output || '').trim();

    output = output
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/, '')
      .replace(/\s*```$/, '');

    // First try normal JSON
    try {
      const data = JSON.parse(output);

      return {
        json: {
          task_id: data.task_id,
          agent: data.agent || 'backend',
          files: data.files || [],
          dependencies: data.dependencies || [],
          remaining_files: data.remaining_files || []
        }
      };
    } catch (_) {
      // If LLM damaged an unused field such as
      // acceptance_criteria_met, recover only fields
      // required by the next workflow node.
    }

    const taskId = extractString(output, 'task_id');
    const agent = extractString(output, 'agent') || 'backend';
    const files = extractArray(output, 'files');

    if (!taskId) {
      throw new Error('task_id is missing');
    }

    if (!Array.isArray(files) || files.length === 0) {
      throw new Error('files array is missing or empty');
    }

    return {
      json: {
        task_id: taskId,
        agent: agent,
        files: files,
        dependencies: [],
        remaining_files: []
      }
    };

  } catch (error) {
    throw new Error(
      `Item ${index} failed: ${error.message}`
    );
  }
});

