const failedWrites = items.filter(
  item => item.json.success !== true ||
          (item.json.files_rejected || []).length > 0
);

if (failedWrites.length > 0) {
  throw new Error(
    `Cannot run tests: ${failedWrites.length} backend task(s) failed to write files`
  );
}

return [
  {
    json: {
      task_id: "TEST-001",
      agent: "backend"
    }
  }
];

const items = $input.all();

return items.map((item, index) => {
  try {
    const data = JSON.parse(item.json.output);

    if (!Array.isArray(data.files) || data.files.length === 0) {
      throw new Error("Repair Agent returned no files");
    }

    return {
      json: {
        task_id: data.task_id,
        agent: data.agent,
        summary: data.summary,
        files: data.files.map(file => ({
          ...file,
          path: file.path.startsWith("backend/")
            ? file.path
            : `backend/${file.path}`
        }))
      }
    };
  } catch (error) {
    throw new Error(
      `Repair output ${index} could not be parsed: ${error.message}`
    );
  }
});

const items = $input.all();

return items.map(item => {
  const currentAttempt = item.json.repair_attempt || 0;
  const nextAttempt = currentAttempt + 1;

  return {
    json: {
      ...item.json,
      repair_attempt: nextAttempt,
      can_repair: nextAttempt <= 3
    }
  };
});

